blocks.mermaid:
flowchart TD
  A["git merge X"] --> B{"¿X ya está contenida en main?"}
  B -- "sí" --> C["Already up to date. (nada que hacer)"]
  B -- "no" --> D{"¿main es ancestro de X?"}
  D -- "sí" --> E["Fast-forward: main avanza hasta X"]
  D -- "no" --> F["Fusión de tres vías desde la base común"]
  F --> G{"¿Ambos cambiaron la misma zona?"}
  G -- "no" --> H["Commit de fusión automático (2 padres)"]
  G -- "sí" --> I["CONFLICT: Git se detiene y te pide decidir"]

