solution:
printf 'function calcularTotal(items, descuento = 0) {
  let total = 0;
  for (const item of items) {
    total += item.precio * item.cantidad;
  }
  return Math.round((total - descuento) * 1.19);
}

module.exports = { calcularTotal };
' > src/total.js

